$(function(){$(window).scroll(function(){if($(window).scrollTop()>= 60){$("header").addClass("fixed-header");}else{$("header").removeClass("fixed-header");}});$('.featured-projects-slider .owl-carousel').owlCarousel({center:true,loop:true,margin:30,nav:false,dots:false,autoplay:true,autoplayTimeout:5000,autoplayHoverPause:false,responsive:{0:{items:1},600:{items:2},1000:{items:3},1200:{items:4}}});$('.count').each(function(){$(this).prop('Counter',0).animate({Counter:$(this).text()},{duration:1000,easing:'swing',step:function(now){$(this).text(Math.ceil(now));}});});function initFeaturedProjectsCarousels(){var carousels = document.querySelectorAll('[data-projects-carousel]');carousels.forEach(function(carousel){var track = carousel.querySelector('[data-projects-track]');var prevBtn = carousel.querySelector('[data-projects-prev]');var nextBtn = carousel.querySelector('[data-projects-next]');var dotsContainer = carousel.querySelector('[data-projects-dots]');var section = carousel.closest('.featured-projects');var countEl = section ? section.querySelector('[data-projects-count]'):null;if(!track){return;}var maxProjects = parseInt(carousel.getAttribute('data-max-projects'),10)|| 6;var allSlides = Array.prototype.slice.call(track.querySelectorAll('[data-project-slide]'));var slides = [];allSlides.forEach(function(slide,idx){if(idx < maxProjects){slide.hidden = false;slides.push(slide);}else{slide.hidden = true;}});if(slides.length === 0){return;}var currentIndex = 0;var visibleCount = 1;var maxIndex = 0;var scrollRaf = null;var resizeTimer = null;var scrollEndTimer = null;var isProgrammaticScroll = false;var targetScrollLeft = 0;function formatTwoDigits(num){return num < 10 ? '0' + num:String(num);}function getSlideOffset(index){if(!slides[index] || !slides[0]){return 0;}return slides[index].offsetLeft - slides[0].offsetLeft;}function measureLayout(){var slideWidth = slides[0].getBoundingClientRect().width;var trackWidth = track.getBoundingClientRect().width;if(slideWidth > 0 && trackWidth > 0){visibleCount = Math.max(1,Math.min(slides.length,Math.round(trackWidth / slideWidth)));}else{visibleCount = 1;}maxIndex = Math.max(0,slides.length - visibleCount);if(currentIndex > maxIndex){currentIndex = maxIndex;}}function getNearestIndex(){var scrollLeft = track.scrollLeft;var closestIdx = 0;var closestDist = Infinity;for(var i = 0;i <= maxIndex;i++){var dist = Math.abs(scrollLeft - getSlideOffset(i));if(dist < closestDist){closestDist = dist;closestIdx = i;}}return closestIdx;}function updateUI(){if(prevBtn){prevBtn.disabled = currentIndex <= 0;prevBtn.setAttribute('aria-disabled',currentIndex <= 0 ? 'true':'false');}if(nextBtn){nextBtn.disabled = currentIndex >= maxIndex;nextBtn.setAttribute('aria-disabled',currentIndex >= maxIndex ? 'true':'false');}if(dotsContainer){var dots = dotsContainer.querySelectorAll('.projects-carousel-dot');dots.forEach(function(dot,idx){var isActive = idx === currentIndex;dot.classList.toggle('is-active',isActive);dot.setAttribute('aria-selected',isActive ? 'true':'false');});}if(countEl){var totalStr = formatTwoDigits(slides.length);if(visibleCount <= 1){countEl.textContent = formatTwoDigits(currentIndex + 1)+ ' / ' + totalStr;}else{var startNum = formatTwoDigits(currentIndex + 1);var endNum = formatTwoDigits(Math.min(slides.length,currentIndex + visibleCount));countEl.textContent = startNum + '–' + endNum + ' / ' + totalStr;}}}function buildDots(){if(!dotsContainer){return;}dotsContainer.innerHTML = '';var pageCount = maxIndex + 1;if(pageCount <= 1){return;}for(var i = 0;i < pageCount;i++){(function(dotIndex){var dot = document.createElement('button');dot.type = 'button';dot.className = 'projects-carousel-dot';dot.setAttribute('role','tab');dot.setAttribute('aria-label','Go to project position ' +(dotIndex + 1)+ ' of ' + pageCount);dot.addEventListener('click',function(){goToSlide(dotIndex);});dotsContainer.appendChild(dot);})(i);}}function goToSlide(index){var targetIndex = Math.max(0,Math.min(maxIndex,index));currentIndex = targetIndex;targetScrollLeft = getSlideOffset(targetIndex);isProgrammaticScroll = true;window.clearTimeout(scrollEndTimer);scrollEndTimer = window.setTimeout(function(){isProgrammaticScroll = false;},650);track.scrollTo({left:targetScrollLeft,behavior:'smooth'});updateUI();}if(prevBtn){prevBtn.addEventListener('click',function(){goToSlide(currentIndex - 1);});}if(nextBtn){nextBtn.addEventListener('click',function(){goToSlide(currentIndex + 1);});}track.addEventListener('scroll',function(){if(isProgrammaticScroll){if(Math.abs(track.scrollLeft - targetScrollLeft)<= 2){isProgrammaticScroll = false;window.clearTimeout(scrollEndTimer);}else{window.clearTimeout(scrollEndTimer);scrollEndTimer = window.setTimeout(function(){isProgrammaticScroll = false;var settled = getNearestIndex();if(settled !== currentIndex){currentIndex = settled;updateUI();}},180);}return;}if(scrollRaf){window.cancelAnimationFrame(scrollRaf);}scrollRaf = window.requestAnimationFrame(function(){var nearest = getNearestIndex();if(nearest !== currentIndex){currentIndex = nearest;updateUI();}});},{passive:true});carousel.addEventListener('keydown',function(event){if(event.key === 'ArrowLeft'){event.preventDefault();goToSlide(currentIndex - 1);}else if(event.key === 'ArrowRight'){event.preventDefault();goToSlide(currentIndex + 1);}});function syncCarousel(){measureLayout();buildDots();currentIndex = getNearestIndex();updateUI();}syncCarousel();window.addEventListener('resize',function(){window.clearTimeout(resizeTimer);resizeTimer = window.setTimeout(function(){measureLayout();buildDots();track.scrollTo({left:getSlideOffset(currentIndex),behavior:'auto'});updateUI();},120);});});}initFeaturedProjectsCarousels();function initFaqAccordion(){var faqRoots = document.querySelectorAll('[data-faq-root]');faqRoots.forEach(function(root){var tabs = Array.prototype.slice.call(root.querySelectorAll('[data-faq-filter]'));var cards = Array.prototype.slice.call(root.querySelectorAll('[data-faq-item]'));function setCardOpen(card,isOpen){var trigger = card.querySelector('[data-faq-trigger]');var icon = card.querySelector('[data-faq-icon]');card.classList.toggle('is-open',isOpen);if(trigger){trigger.setAttribute('aria-expanded',isOpen ? 'true':'false');}if(icon){icon.textContent = isOpen ? '−':'+';}}cards.forEach(function(card){var trigger = card.querySelector('[data-faq-trigger]');if(!trigger){return;}trigger.addEventListener('click',function(){var currentlyOpen = card.classList.contains('is-open');setCardOpen(card,!currentlyOpen);});});tabs.forEach(function(tab){tab.addEventListener('click',function(){var filter = tab.getAttribute('data-faq-filter')|| 'all';tabs.forEach(function(t){var active = t === tab;t.classList.toggle('is-active',active);t.setAttribute('aria-selected',active ? 'true':'false');});var firstVisible = null;cards.forEach(function(card){var cat = card.getAttribute('data-faq-category')|| 'all';var matches = filter === 'all' || cat === filter;card.hidden = !matches;if(matches && !firstVisible){firstVisible = card;}if(!matches){setCardOpen(card,false);}});var anyOpenVisible = cards.some(function(card){return !card.hidden && card.classList.contains('is-open');});if(!anyOpenVisible && firstVisible){setCardOpen(firstVisible,true);}});});});}initFaqAccordion();function initConversionBookingCard(){var bookingCards = document.querySelectorAll('[data-booking-card]');bookingCards.forEach(function(card){var rolePills = Array.prototype.slice.call(card.querySelectorAll('[data-role-pill]'));var servicePills = Array.prototype.slice.call(card.querySelectorAll('[data-service-pill]'));var ctaLink = card.querySelector('[data-booking-cta]');function updateCtaHref(){if(!ctaLink){return;}var selectedRole = '';rolePills.forEach(function(pill){if(pill.classList.contains('is-selected')){selectedRole = pill.getAttribute('data-role-pill')|| '';}});var selectedServices = [];servicePills.forEach(function(pill){if(pill.classList.contains('is-selected')){var val = pill.getAttribute('data-service-pill');if(val){selectedServices.push(val);}}});var params = [];if(selectedRole){params.push('role=' + encodeURIComponent(selectedRole));}if(selectedServices.length > 0){params.push('services=' + encodeURIComponent(selectedServices.join(', ')));}ctaLink.setAttribute('href',params.length > 0 ? '/contact?' + params.join('&'):'/contact');}rolePills.forEach(function(pill){pill.addEventListener('click',function(){rolePills.forEach(function(p){var active = p === pill;p.classList.toggle('is-selected',active);p.setAttribute('aria-pressed',active ? 'true':'false');});updateCtaHref();});});servicePills.forEach(function(pill){pill.addEventListener('click',function(){var next = !pill.classList.contains('is-selected');pill.classList.toggle('is-selected',next);pill.setAttribute('aria-pressed',next ? 'true':'false');updateCtaHref();});});updateCtaHref();});}function prefillContactFormFromQuery(){var messageField = document.getElementById('exampleFormControlTextarea1');if(!messageField || !window.location.search){return;}var params = new window.URLSearchParams(window.location.search);var role = params.get('role');var services = params.get('services');if(!role && !services){return;}var lines = [];if(role){lines.push('Role: ' + role);}if(services){lines.push('Services Requested: ' + services);}lines.push('Property Address & Preferred Date: ');if(!messageField.value){messageField.value = lines.join('\n');}}initConversionBookingCard();prefillContactFormFromQuery();function scrollToTop(){window.scrollTo({top:0,behavior:'smooth'});}const btn = document.getElementById("scrollToTopBtn");if(btn){btn.addEventListener("click",scrollToTop);window.onscroll = function(){if(document.documentElement.scrollTop > 100 || document.body.scrollTop > 100){btn.style.display = "flex";}else{btn.style.display = "none";}};}AOS.init({once:true,});});
